// Task spec as data: handoff contract, testable blind (plain JS)
const triageTask = {
  description: "Classify the ticket into exactly one of [billing, shipping, returns].",
  expected_output: '{"category": "<label>", "confidence": 0..1}',
  contextFrom: [],                       // first task: raw ticket only
  agent: "triage-specialist",
};
const decideTask = {
  description: "Apply POLICY TEXT to the triaged facts; approve or deny.",
  expected_output: '{"approved": bool, "reason": "<=12 words"}',
  contextFrom: ["triageTask.category", "triageTask.confidence"], // named, minimal
  agent: "policy-decider",
};
// Downstream consumes triageTask.category blind — shape guaranteed by spec.

// Handoff assembler: contract-checked before downstream starts (plain JS)
function handoff(task, priorOutputs) {
  const missing = (task.contextFrom || []).filter((k) => !(k in priorOutputs));
  if (missing.length) return { ok: false, error: "missing-context:" + missing.join(",") };
  const input = {};
  for (const k of task.contextFrom) input[k] = priorOutputs[k];
  return { ok: true, input };
}
// handoff(decideTask, { "triageTask.category": "shipping" }) → missing confidence!
// Mechanical gate: downstream never starts on incomplete handoffs.

